/**
 * Real brand marks, keyed by provider id.
 *
 * Every path here is the vendor's actual logo, never drawn by hand:
 *
 * - `@lobehub/icons` (MIT) — AWS, Azure, Google Cloud, Nebius, Lambda,
 *   Together;
 * - `simple-icons` (CC0) — Modal, Kubernetes;
 * - CoreWeave and RunPod come from the provider logos published by SkyPilot's
 *   GPU Compass (gpus.skypilot.co/providers/). RunPod ships as an SVG, so its
 *   path is verbatim. CoreWeave ships only a 256px PNG, so its mark was traced
 *   off that bitmap and refitted to a 24-unit box — the geometry is all
 *   straight edges, so the trace is exact rather than approximate.
 *
 * Vendored as path data instead of taking the dependencies — a handful of marks
 * is not worth 3,000, and it keeps the bundle to the bytes we actually render.
 *
 * The logos are trademarks of their respective owners, shown here to identify
 * the provider a row refers to.
 *
 * Only vendors whose real mark exists get an entry; anything else falls back to
 * a drawn glyph or monogram in the site's own blue rather than a fabricated
 * brand mark. See `provider-icon.tsx`.
 */
export type BrandMark = {
  /** Coordinate system the paths are drawn in. */
  viewBox: string;
  /**
   * Filled subpaths, drawn with `evenodd` so cut-outs stay open. A plain string
   * takes the mark's `color`; the object form is for the few logos that are
   * genuinely two-tone, so we don't flatten them into one hue.
   */
  paths: (string | { d: string; color: string })[];
  /**
   * The vendor's own brand colour, as rendered.
   *
   * Some are darkened from the official hex: a 24px mark on white has to clear
   * roughly 3:1 to read as a shape at all, and AWS orange (2.1:1), Nebius lime
   * (1.15:1) and Modal green (1.5:1) all fall well under. Those three are
   * scaled toward black until they clear it, which holds the hue while making
   * the mark visible. `official` records what was published, so the deviation
   * is auditable rather than a typo.
   */
  color: string;
  /** The published brand hex, when `color` had to be darkened to be legible. */
  official?: string;
};

